"""Record post-analysis operational choices and complete numerical comparators."""
from pathlib import Path
import hashlib
import pandas as pd
from dlpro.experiment_core import save_json
out=Path('results/experiment_choices');out.mkdir(exist_ok=True)
classification=pd.read_csv('results/model_validation/classification_comparison.csv');classification.to_csv(out/'classification_all_recipes.csv',index=False)
native=pd.read_csv('results/sr_refined/projection_ablation_native.csv');native=native.groupby(['method','replicate'])[['psnr','ssim']].mean().reset_index();native['source']='projection_ablation_seed42'
context=pd.read_csv('results/sr_context/metrics_per_window.csv');context=context[((context.seed==42)&(context.method=='subpixel_cnn'))|context.method.isin(['bilinear','bicubic','projected_bicubic'])].groupby(['method','replicate'])[['psnr','ssim']].mean().reset_index();context['method']=context.method.replace({'subpixel_cnn':'context_count_cnn'});context['source']='context_seed42'
pd.concat([native,context]).to_csv(out/'sr_native_comparison.csv',index=False)
shape=pd.read_csv('results/sr_refined/projection_ablation_shape.csv');shape=shape.groupby('method')[['oe_ssim_100bp','oe_ssim_200bp']].mean().reset_index();context=pd.read_csv('results/sr_context/known_recovery.csv');context=context[context.method.isin(['subpixel_cnn','bilinear','bicubic','projected_bicubic'])];
for method,g in context.groupby('method'):shape.loc[len(shape)]=['context_count_cnn' if method=='subpixel_cnn' else method,g.context_oe_ssim_original_100bp.mean(),g.context_oe_ssim_original.mean()];shape.to_csv(out/'sr_shape_comparison.csv',index=False)
downstream=pd.read_csv('results/sr_context/downstream_summary.csv');downstream=downstream[downstream.method.isin(['bilinear','bicubic','projected_bicubic','subpixel_cnn'])].reset_index(drop=True);downstream['method']=downstream.method.replace({'subpixel_cnn':'context_count_cnn'});pred=pd.read_csv('results/sr_refined/projection_ablation_predictions.csv')
from sklearn.metrics import f1_score
for method,g in pred.groupby('method'):downstream.loc[len(downstream)]=[method,len(g),float((g.true_type==g.predicted_type).mean()),float(f1_score(g.true_type,g.predicted_type,labels=['CHID','CHIN','OPCID'],average='macro',zero_division=0)),float('nan')]
downstream.to_csv(out/'sr_downstream_comparison.csv',index=False)
sources=['results/model_validation/classification_comparison.csv','results/sr_refined/projection_ablation_native.csv','results/sr_refined/projection_ablation_shape.csv','results/sr_context/metrics_per_window.csv','results/sr_context/known_recovery.csv','results/sr_context/downstream_summary.csv','results/sr_refined/projection_ablation_predictions.csv'];save_json(out/'sources.json',{p:hashlib.sha256(Path(p).read_bytes()).hexdigest() for p in sources})
save_json(out/'choices.json',dict(status='Post-analysis operational freeze, not preregistration or independent test selection',classification=dict(primary='fine_consistent_ensemble',location='results/classification_fine',reason='Keep fixed three-scale repeat-consistency ensemble; avoid choosing recipe by maximum observed test accuracy',input='50/100/200bp contact images only; no label-derived length or bounds',labels='Original344 mutually exclusive course rows retained; overlapping/nested biological annotations explicitly audited, not silently relabelled',imbalance='Balanced location sampling and macroF1 validation;26CHID limit remains',rejected_claim='CHID recognition solved',alternatives='Matched extended training, span auxiliary, shape forest, kernel and gate retained as comparators; gate high accuracy has lower CHID recall'),superresolution=dict(primary='projected_first_round_cnn',location='results/sr_refined/projection_ablation_*',reason='Use simple measured-count projection of established CNN for count-consistent reconstruction; deeper model adds small native gain without clear100bp structural or downstream gain',required_comparators=['bilinear','bicubic','projected_bicubic','first_round_cnn','projected_first_round_cnn','context_count_cnn'],tradeoff='UnconstrainedCNN retains better nativePSNR/downstream in this benchmark; primary choice prioritizes count fidelity and100bp shape with explicit loss of those benefits',not_learned_evidence='200bp preservation guaranteed by40bp projection',limitation='Choice made after exploratory outcomes; no independent final-test claim'),discovery=dict(primary='support-aware morphology,64candidate fixed budget',high_recall_alternative='Training90%recall calibration,6400bp spacing;widebudget',candidate_followup=['U001','U004','U005','U007'],new_structure_class_confirmed=False),report_generation='Paused; do not execute document builders'))
print(shape.to_string(index=False))
